mapper.select:


    r.deleted = FALSE
    AND r.received_at >= #{timeRange.startAt}
    AND r.received_at < #{timeRange.endAt}

        AND FALSE


            AND c.seller_id IN
            #{sellerId}


    AND r.id = #{query.receiptId}
    AND r.customer_id = #{query.customerId}
    AND r.method = #{query.method}
    AND r.entry_type = #{query.entryType}

        AND r.entry_type = 'NORMAL'
        AND GREATEST(r.amount - reversed.reversedAmount - used.usedAmount, 0) > 0


